private static double calculateAmountForPerformance(Performance perf, Play play) {
    double amount = 0;
    switch (play.getType()) {
        case "tragedy":
            amount = 40000;
            if (perf.getAudience() > 30) {
                amount += 1000 * (perf.getAudience() - 30);
            }
            break;
        case "comedy":
            amount = 30000;
            if (perf.getAudience() > 20) {
                amount += 10000 + 500 * (perf.getAudience() - 20);
            }
            amount += 300 * perf.getAudience();
            break;
        default:
            throw new IllegalArgumentException("Unknown type: " + play.getType());
    }
    return amount;
}

private static int calculateVolumeCredits(Performance perf, Play play) {
    int credits = 0;
    switch (play.getType()) {
        case "tragedy":
            credits += Math.max(perf.getAudience() - 30, 0);
            break;
        case "comedy":
            credits += Math.max(perf.getAudience() - 30, 0);
            credits += Math.floor(perf.getAudience() / 5);
            break;
        default:
            throw new IllegalArgumentException("Unknown type: " + play.getType());
    }
    return credits;
}
